    for digit, indices in digit_indices.items():
        if len(indices) >= 2:
            # Calculate the minimum distance between any two consecutive occurrences
            for j in range(1, len(indices)):
                distance = indices[j] - indices[j-1]
                min_distance = min(min_distance, distance)

    # If no digit appears twice, output -1
    if min_distance == float('inf'):
        print(-1)
    else:
        print(min_distance)
